package com.learnagent.memory;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/flashcards")public class FlashcardController{private final FlashcardService service;public FlashcardController(FlashcardService service){this.service=service;}@PostMapping("/candidates/generate")public ResponseEntity<List<MemoryDtos.CardView>>generate(@RequestBody MemoryDtos.GenerateRequest request){return ResponseEntity.status(HttpStatus.CREATED).body(service.generate(request));}@GetMapping public List<MemoryDtos.CardView>list(@RequestParam(required=false)UUID courseId,@RequestParam(defaultValue="CANDIDATE")FlashcardStatus status){return service.list(courseId,status);}@GetMapping("/{id}")public MemoryDtos.CardView get(@PathVariable UUID id){return service.get(id);}@PutMapping("/{id}")public MemoryDtos.CardView update(@PathVariable UUID id,@RequestBody MemoryDtos.CardUpdate request){return service.update(id,request);}@PostMapping("/{id}/approve")public MemoryDtos.CardView approve(@PathVariable UUID id){return service.approve(id);}@PostMapping("/approve-batch")public List<MemoryDtos.CardView>approveBatch(@RequestBody MemoryDtos.BatchApprove request){return service.approveBatch(request.cardIds());}@PostMapping("/{id}/suspend")public MemoryDtos.CardView suspend(@PathVariable UUID id){return service.suspend(id);}@PostMapping("/{id}/reject")public MemoryDtos.CardView reject(@PathVariable UUID id){return service.reject(id);}}
